use anyhow :: { Context , Result } ; use lazy_static :: lazy_static ; use petgraph :: graph :: { Graph , NodeIndex } ; use petgraph :: visit :: Bfs ; use rayon :: prelude :: * ; use regex :: Regex ; use serde :: { Deserialize , Serialize } ; use cargo_metadata :: { MetadataCommand , DependencyKind } ; use std :: collections :: HashMap ; use std :: fs ; use std :: path :: { Path , PathBuf } ; use std :: process :: Command ; use std :: collections :: hash_map :: DefaultHasher ; use std :: hash :: { Hash , Hasher } ; fn parse_cargo_lock_for_git_deps (lock_path : & Path) -> Result < Vec < CrateInfo > > { let content = fs :: read_to_string (lock_path) . context ("Failed to read Cargo.lock") ? ; let mut deps = Vec :: new () ; let mut seen = std :: collections :: HashSet :: new () ; for caps in PACKAGE_RE . captures_iter (& content) { let name = caps . get (1) . map (| m | m . as_str ()) . unwrap_or ("") ; let version = caps . get (2) . map (| m | m . as_str ()) . unwrap_or ("") ; let source = caps . get (3) . map (| m | m . as_str ()) . unwrap_or ("") ; if ! source . starts_with ("git+") { continue ; } let url_part = source . strip_prefix ("git+") . unwrap_or (source) ; let url = url_part . split ('#') . next () . unwrap_or (url_part) ; if let Some (caps) = GITHUB_URL_RE . captures (url) { let owner = caps . get (1) . map (| m | m . as_str ()) . unwrap_or ("") ; let repo = caps . get (2) . map (| m | m . as_str ()) . unwrap_or ("") ; let key = format ! ("{}:{}:{}" , owner , repo , version) ; if seen . contains (& key) { continue ; } seen . insert (key) ; let repo_url = format ! ("https://github.com/{}/{}" , owner , repo) ; eprintln ! ("  [Cargo.lock] Found git dep: {} v{} -> {}" , name , version , repo_url) ; deps . push (CrateInfo { name : Some (name . to_string ()) , version : Some (version . to_string ()) , repository : Some (repo_url) , manifest_path : lock_path . display () . to_string () , }) ; } } Ok (deps) }